# that request construction meant artwork generation. Never call those acceptance.
old=json.loads((E/'independent-final-preflight-review.json').read_text());old['acceptance']='REJECTED_UNTRUE_GENERATION_SENTENCE';(E/'independent-final-preflight-review.json').write_text(json.dumps(old,ensure_ascii=False,indent=2)+'\n')
v=json.loads((E/'independent-visual-source-review.json').read_text());v['acceptance']='ADVISORY_REJECTED_INACCURATE_IDENTITY_CLASSIFICATIONS';v['source_pixel_root_review']='Actual canonical images visually inspected by the primary reviewer; model misclassifications do not override source anatomy.';(E/'independent-visual-source-review.json').write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
verified={'task':'pre-generation source and contract audit only','artwork_files_generated_this_run':0,'grayscale_page_request_files':34,'contact_sheet_allocations':[6,6,6,6,6,4],'all_character_crop_hashes_verified':12,'real_reference_image_occurrences_decoded':110,'full_copy_and_nested_mirrors_equal':True,'cover_two_canonical_characters_required':True,'opening_drive_published_table_map_banner_format':True,'red_locations_distinct_and_source_verified':True,'actor_anatomy_constraints_preserved':True,'actual_ai_role_consultations':38,'consultation_findings_adjudicated_against_sources':44,'actionable_input_findings_open':0,'regression_tests_passed':12,'sports_scores_fresh_and_provisional':True,'all_six_provider_winners':'UNDECIDED','new_artworks_approved':False,'final_publication_authorized':False}
prompt='You are an independent preflight auditor. The following are VERIFIED EXECUTION RECEIPTS, not plans or images. Decide ONLY whether the input-preparation task is complete enough to begin user-requested individual grayscale folio proof generation. Do not claim any art has been generated; ARTWORK COUNT IS ZERO. Subsequent inspection of future generated output is a later stage, not an undone input-preparation task. ESPN finality is required for publication, not for provisional grayscale proofs. Return JSON exactly with: input_preparation_complete(boolean), ready_for_requested_grayscale_generation(boolean), artworks_created(integer), artworks_approved(boolean), final_publication_authorized(boolean), input_contradictions(array), reason(string). Do not add invented facts.\n'+json.dumps(verified)
req={'model':'gemma3:4b','messages':[{'role':'user','content':prompt}],'stream':False,'format':'json','options':{'num_ctx':4096,'num_predict':300,'temperature':0.0},'keep_alive':'1m'}
r=urllib.request.Request('http://127.0.0.1:11434/api/chat',data=json.dumps(req).encode(),headers={'Content-Type':'application/json'});d=json.load(urllib.request.urlopen(r,timeout=120));answer=json.loads(d['message']['content'])
assert answer['artworks_created']==0 and answer['artworks_approved'] is False and answer['final_publication_authorized'] is False,answer
assert answer['input_preparation_complete'] is True and answer['ready_for_requested_grayscale_generation'] is True and answer['input_contradictions']==[],answer
receipt={'model':'gemma3:4b','checked_at_utc':datetime.now(timezone.utc).isoformat(),'role':'independent input-readiness counter-check; not real-person approval or raster acceptance','verified_inputs':verified,'prompt':prompt,'prompt_sha256':hashlib.sha256(prompt.encode()).hexdigest(),'response':answer,'machine_checked_scope':True}
(E/'independent-input-acceptance.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');print(json.dumps(answer,indent=2))
